/* Pool registry - see pools.h for why this is its own file.
 *
 * The shape, one paragraph (POOLS.md sections 3.1-3.5):
 *
 *   - A pool is a **slot in a registry**, never a first-class value. What the library
 *     hands out is a handle: `{ index, generation }`, a plain copyable value.
 *   - Every slot carries a generation. Dropping a pool bumps its generation, so a handle
 *     that outlived its pool fails the check instead of reading freed memory; the library
 *     turns that into `failure(staleHandle)` with a source position (ruling: a bug traps, a
 *     condition is a value - POOLS.md section 3.3).
 *   - Regions and arena blocks are **one tree**: a pool's parent is either another pool
 *     or the arena level that created it. Dropping a pool drops its whole subtree, and
 *     leaving a block drops every pool still hanging off that level. That is the hook the
 *     generator emits, one line per release point.
 *   - Membership is the whole point: because the owner is the parent (not the handle),
 *     "copy the handle" and "two owners free the same slot" cannot happen, and a free list
 *     cannot grow a cycle out of user data.
 *
 * A pool **owns its own memory**, and that is the point of it (POOLS.md section 2): data,
 * free list and nested pools each sit in blocks the pool owns, and the pool threads them
 * into a side chain / tree. The arena does not own those blocks -- it owns their
 * **lifetime**, and releasing a place releases the pools created in it, which releases
 * their plates. So `shrink` can really shrink and `release` can really give memory back,
 * while `new T[n]` from the arena can only wait for the place to end.
 *
 * Because the pool owns the blocks, nothing here is freed piece by piece behind the user's
 * back either: `remove` reuses a slot, `clear` flips an epoch, and only `release` (or the
 * place ending) hands the plate back.
 */

#include "pools.h"

/* The runtime text below is the only copy of this logic: it is what runs, so it is what has
 * to be read and tested. It mentions no arena: the arena is where memory comes from, the
 * pool is the side chain that makes it reusable. Split across several `bufPuts` calls
 * because one literal longer than 4095 characters draws -Woverlength-strings. */
void poolsEmitRuntime(Arena *a, Buf *out) {
    (void)a;
    bufPuts(out, "/* ---- pool registry (POOLS.md) ----\n * A pool is an index here, never a value: the library hands out `{ index, generation }`,\n * and dropping bumps the generation, so a handle that outlived its pool fails a check\n * instead of reading freed memory.\n *\n * The picture: the arena is a chain of blocks and nothing else - it is where memory\n * comes from. A pool is a structure of its own: it links what it holds (nested pools)\n * as a side chain beside the arena; the memory its containers use is its OWN plate (a chain\n * of blocks it owns, and can give back when a buffer is replaced). A zone is the head of one such\n * side chain - a virtual grouping, one per place, holding the pools created there. It\n * is deliberately not embedded in the arena's stack: leaving a place has to enumerate\n * the zone's own chain, and a block rollback must not be able to tear that structure\n * out from under it.\n *\n * `extc_pool_zoneLeaveTo(mark)` pops to a mark rather than popping blindly, so early\n * exits (`return`, `break`, `continue`) cannot leave the stack unbalanced: a leave is\n * always expressed as \"back to the depth this place started at\".\n *\n * Emitted only for a program that declares a pool extern. */\ntypedef struct ExtcBlock { struct ExtcBlock *next; int64_t size; } ExtcBlock;\ntypedef struct ExtcPool {\n    uint64_t generation;\n    int64_t  parent;        /* parent pool, or -1 for a root of its zone */\n    int64_t  zone;          /* the zone (place) that owns it */\n    int64_t  firstChild;    /* nested pools: a container of containers */\n    int64_t  nextSibling;   /* the parent's child list */\n    int64_t  zoneNext;      /* the zone's list of pool trees (the side chain) */\n    int64_t  freeNext;      /* the free list of slots */\n    int64_t  live;\n    int64_t  color;        /* 出生时它那个 zone 的颜色（染色：一次翻色作废整棵树）*/\n    ExtcBlock *blocks;     /* THE PLATE: the blocks this pool owns (never borrowed) */\n    int64_t  bytes;        /* what those blocks hold right now */\n} ExtcPool;\ntypedef struct ExtcZone { int64_t firstPool, parent; int64_t color; } ExtcZone;\nstatic ExtcPool *extc_pools        = NULL;\nstatic int64_t   extc_poolCap      = 0;\nstatic int64_t   extc_poolLiveN    = 0;\nstatic int64_t   extc_poolFreeHead = -1;\nstatic int64_t   extc_poolBytesAll = 0;   /* live bytes over all pools (evidence) */\n");
    bufPuts(out, "/* 色宽：3 位。位宽**只是检测强度**（命中 1/8），不参与正确性 —— 色只做否决，\n * 活性权威永远是 n / 空洞链 / 世代（POOLS.md 7.4 第 2 条与 7.6 第 4 条）。 */\n#ifndef EXTC_ZONE_COLOR_BITS\n#define EXTC_ZONE_COLOR_BITS 3\n#endif\nstatic ExtcZone *extc_zones        = NULL;\nstatic int64_t   extc_zoneCap      = 0;\nstatic int64_t   extc_zoneTop      = -1;\nint64_t extc_pool_live(void) { return extc_poolLiveN; }\nint64_t extc_pool_capacity(void) { return extc_poolCap; }\nint64_t extc_pool_zoneDepth(void) { return extc_zoneTop + 1; }\n/* Entering a place: push the head of a side chain and hand back its mark. */\nint64_t extc_pool_zoneEnter(void) {\n    int64_t id = extc_zoneTop + 1;\n    if (id >= extc_zoneCap) {\n        int64_t want = extc_zoneCap ? extc_zoneCap * 2 : 64;\n        ExtcZone *grown = (ExtcZone *)realloc(extc_zones, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        extc_zones = grown; extc_zoneCap = want;\n    }\n    /* 染色：**翻一位**（加一取模）。同一个下标是循环体每轮复用的那个地方，所以上一轮\n     * 出生在这儿的池，颜色必然对不上 ⇒ 一次比较就作废整棵树，一个槽都不用走。\n     * 全新的一格（realloc 之后初值 0）也从 1 开始，与「从未用过」的 0 区分开。 */\n    extc_zones[id].color = (extc_zones[id].color + 1) & ((1 << EXTC_ZONE_COLOR_BITS) - 1);\n    if (extc_zones[id].color == 0) extc_zones[id].color = 1;\n    extc_zones[id].firstPool = -1;\n    extc_zones[id].parent    = extc_zoneTop;\n    extc_zoneTop = id;\n    return id;\n}\nstatic void extc_pool_releaseBlocks(ExtcPool *r) {\n    ExtcBlock *b = r->blocks;\n    while (b) { ExtcBlock *next = b->next; extc_poolBytesAll -= b->size; free(b); b = next; }\n    r->blocks = NULL; r->bytes = 0;\n}\nstatic void extc_pool_freeSelf(int64_t rid) {\n    ExtcPool *r = &extc_pools[rid];\n    /* The plate goes back here, and this is the real release: the arena only ever takes\n     * whole blocks back at a place boundary, the pool hands its own memory back at once. */\n    extc_pool_releaseBlocks(r);\n    r->live = 0; r->parent = -1; r->firstChild = -1;\n    r->freeNext = extc_poolFreeHead;\n    extc_poolFreeHead = rid;\n    extc_poolLiveN--;\n}\nstatic void extc_pool_unlinkZone(int64_t rid) {\n    int64_t zi = extc_pools[rid].zone;\n    if (zi < 0) return;\n");
    bufPuts(out, "    {\n        int64_t *link = &extc_zones[zi].firstPool;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_pools[rid].zoneNext; break; }\n            link = &extc_pools[*link].zoneNext;\n        }\n    }\n}\nvoid extc_pool_drop(int64_t rid) {\n    int64_t child, parent;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return;\n    child = extc_pools[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_pools[child].nextSibling;\n        extc_pool_drop(child);\n        child = next;\n    }\n    parent = extc_pools[rid].parent;\n    if (parent >= 0) {\n        int64_t *link = &extc_pools[parent].firstChild;\n        while (*link >= 0) {\n            if (*link == rid) { *link = extc_pools[rid].nextSibling; break; }\n            link = &extc_pools[*link].nextSibling;\n        }\n    }\n    /* A pool is on the zone chain whether or not it has a parent, so dropping it\n     * always has to leave that chain -- a stale link would be followed by the next\n     * zone sweep, and the record may already belong to somebody else. */\n    extc_pool_unlinkZone(rid);\n    extc_pool_freeSelf(rid);\n}\n");
    /* 池的创建与提权那一扇门单独一个字符串字面量：一个超过 4095 字符的字面量会刷
     * -Woverlength-strings。 */
    bufPuts(out, "/* A pool is created with its container, inside some place; `parent` is another pool when\n * the container nests one, -1 otherwise. No arena and no level number is passed: the pool\n * starts with an empty plate and takes blocks of its own as the container grows. */\n/* THE PROMOTION HOOK (POOLS.md 3.1 / MEMORY-SAFETY 3.1).\n *\n * `zone` names the place this pool is BORN in -- normally the current top, which is what\n * `extc_pool_new` passes. The arena has the same door: a function that hands its allocation\n * to the caller's place takes a hidden `__extc_home` arena, so `new` inside it lands where\n * the value ends up. A container built inside a loop body and then stored into something\n * that outlives the loop needs exactly that: without it its plate dies with the iteration\n * (measured: `vector<vector<i32>>` pushes three inner vectors, and after the loop\n * `extc_pool_live()` is back to 1 -- all three inner pools are gone while the outer plate\n * still holds values pointing at them; ASan says heap-use-after-free).\n *\n * The zone index is a plain integer and equals depth - 1 (`zoneEnter` hands out\n * `extc_zoneTop + 1`), so naming a place costs nothing and never dangles: the target zone\n * is on the stack whenever a promoted construction runs. */\nint64_t extc_pool_new_at(int64_t parent, int64_t zi) {\n    int64_t idx;\n    ExtcPool *r;\n    if (zi < 0 || zi > extc_zoneTop) return -1;   /* the named place is not on the stack */\n    if (extc_poolFreeHead >= 0) {\n        idx = extc_poolFreeHead;\n        extc_poolFreeHead = extc_pools[idx].freeNext;\n    } else {\n        int64_t want = extc_poolCap ? extc_poolCap * 2 : 64, i;\n        ExtcPool *grown = (ExtcPool *)realloc(extc_pools, (size_t)want * sizeof *grown);\n        if (!grown) return -1;\n        for (i = extc_poolCap; i < want; i++) {\n            grown[i].generation = 0; grown[i].parent = -1; grown[i].zone = -1;\n            grown[i].firstChild = -1; grown[i].nextSibling = -1;\n            grown[i].zoneNext = -1; grown[i].freeNext = -1; grown[i].live = 0; grown[i].blocks = NULL; grown[i].bytes = 0;\n        }\n        extc_pools = grown; idx = extc_poolCap; extc_poolCap = want;\n    }\n    r = &extc_pools[idx];\n    if (r->live) return -1;\n    r->generation++;\n    r->live = 1; r->parent = parent; r->zone = zi;\n    r->color = extc_zones[zi].color;   /* 出生色：与 zone 当前色不符 ⇒ 那个地方死过 */\n    r->firstChild = -1; r->nextSibling = -1; r->zoneNext = -1;\n    r->blocks = NULL; r->bytes = 0;\n    /* TWO CHAINS, attached separately (POOLS.md 7.7). The zone root chain is LIFETIME: a place\n     * releases everything in it, and it has to see every pool, nested or not. The parent\n     * chain is LOGICAL: dropping a container takes the containers nested inside it.\n     * Attaching only the parent chain would hide a nested pool from its own place, so a\n     * pool created in a deeper block would outlive it. */\n    r->zoneNext = extc_zones[zi].firstPool;\n    extc_zones[zi].firstPool = idx;\n    if (parent >= 0) {\n        r->nextSibling = extc_pools[parent].firstChild;\n        extc_pools[parent].firstChild = idx;\n    }\n    extc_poolLiveN++;\n    return idx;\n}\n/* 不放宽时的常规入口：生在当前顶上 */\nint64_t extc_pool_new(int64_t parent) { return extc_pool_new_at(parent, extc_zoneTop); }\nuint64_t extc_pool_generation(int64_t rid) {\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return 0;\n    return extc_pools[rid].generation;\n}\n/* Keep the pool, mark its slots reusable: the nested tree is walked and dropped. The\n * memory stays where it is (the arena releases it at the end of the place), so `reset`\n * is about reuse, not about returning memory - which is what makes it cheap to call. */\nvoid extc_pool_reset(int64_t rid) {\n    int64_t child;\n");
    bufPuts(out, "    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return;\n    child = extc_pools[rid].firstChild;\n    while (child >= 0) {\n        int64_t next = extc_pools[child].nextSibling;\n        extc_pool_drop(child);\n        child = next;\n    }\n    extc_pools[rid].firstChild = -1;\n}\n/* Leaving a place: drop every zone from the top down to `mark` (the depth this place\n * started at). Expressed as a mark rather than one pop, so a path that skipped a leave\n * still ends up balanced. */\nvoid extc_pool_zoneLeaveTo(int64_t mark) {\n    while (extc_zoneTop >= mark && extc_zoneTop >= 0) {\n        int64_t zi = extc_zoneTop;\n        int64_t rid = extc_zones[zi].firstPool;\n        while (rid >= 0) {\n            int64_t next = extc_pools[rid].zoneNext;\n            extc_pool_drop(rid);\n            rid = next;\n        }\n        extc_zoneTop = extc_zones[zi].parent;\n    }\n}\n");
    /* The plate is its own literal: one string longer than 4095 characters draws
     * -Woverlength-strings, which the build treats as a warning worth avoiding. */
    bufPuts(out, "/* ---- the plate: a pool's own memory (POOLS.md 2.1, PLAN #85) ----\n *\n * The container asks for a block here, not for arena memory, and gives the old block back\n * when it replaces it. That is the whole reason a doubling buffer no longer leaves every\n * old generation behind (the 9,900 KB reading in POOLS.md 1): the arena can only take whole\n * blocks back at a place boundary, a pool plate takes a block back the moment it is free.\n *\n * Every block is zeroed on the way out, so a fresh allocation still reads as zero -- the\n * promise the language makes about `new`, kept here without the arena. */\nvoid *extc_pool_take(int64_t rid, int64_t bytes) {\n    ExtcBlock *b;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return NULL;\n    if (bytes <= 0) bytes = 1;\n    b = (ExtcBlock *)malloc(sizeof(ExtcBlock) + (size_t)bytes);\n    if (!b) { fprintf(stderr, \"trap: out of pool memory (this allocation wanted %lld bytes)\\n\",\n                      (long long)bytes); extc_die(1); }\n    memset((void *)(b + 1), 0, (size_t)bytes);\n    b->next  = extc_pools[rid].blocks;\n    b->size  = bytes;\n    extc_pools[rid].blocks  = b;\n    extc_pools[rid].bytes  += bytes;\n    extc_poolBytesAll      += bytes;\n    return (void *)(b + 1);\n}\n/* Give one block back. The block is found by its address -- the caller holds a view, not a\n * block id -- and the walk is over this pool's own chain, which is short: a container that\n * grows by 1.5x has one live block plus whatever it has not replaced yet. */\n");
    bufPuts(out, "/* 与 `take` 相同，只是**不清零**：给「马上就会被整片写掉」的那些块用（池自己的槽表尤其如此 ——\n * 一张全新的表在 `pFree` 的判据下天然全空闲，一个字节都不必写，连页都不必碰）。\n * 用户可见的内存不走这条路：`new T[n]` 的「新分配读作 0」是语言承诺，那条路照旧清零。 */\nvoid *extc_pool_take_raw(int64_t rid, int64_t bytes) {\n    ExtcBlock *b;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return NULL;\n    if (bytes <= 0) bytes = 1;\n    b = (ExtcBlock *)malloc(sizeof(ExtcBlock) + (size_t)bytes);\n    if (!b) { fprintf(stderr, \"trap: out of pool memory (this allocation wanted %lld bytes)\\n\",\n                      (long long)bytes); extc_die(1); }\n    /* **金丝雀**（判据专用，见 tests/pool/run.sh）：把 raw 块填成 0xAA ⇒ 任何「先读后写」的\n     * raw 列都当场现形。选 0xAA 有两个理由：① 一眼认得出（不是零）；② 池自己的簿记也走这条\n     * 路，而 `pFree` 的判据是 `lo == 0 || lo > cap` —— 0xAAAAAAAA 远大于 cap ⇒ 仍读作空闲。\n     * 只有 `-DEXTC_POISON_RAW=1` 编译时才存在，正常产物零开销。 */\n#ifdef EXTC_POISON_RAW\n    memset((void *)(b + 1), 0xAA, (size_t)bytes);\n#endif\n    b->next  = extc_pools[rid].blocks;\n    b->size  = bytes;\n    extc_pools[rid].blocks  = b;\n    extc_pools[rid].bytes  += bytes;\n    extc_poolBytesAll      += bytes;\n    return (void *)(b + 1);\n}\nint64_t extc_pool_give(int64_t rid, void *p) {\n    ExtcBlock **link;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live || !p) return 0;\n    link = &extc_pools[rid].blocks;\n    while (*link) {\n        ExtcBlock *b = *link;\n        if ((void *)(b + 1) == p) {\n            *link = b->next;\n            extc_pools[rid].bytes -= b->size;\n            extc_poolBytesAll     -= b->size;\n            free(b);\n            return 1;\n        }\n        link = &b->next;\n    }\n    return 0;\n}\n/* 染色那一层：这个池的出生色 vs 它那个 zone 现在的色。\n * 不等 ⇒ **一定**死过（那个地方退出过）；相等不保证活（位宽会绕回、垃圾内存会碰巧命中），\n * 所以它只做否决，活性仍看 n / 空洞链 / 世代（POOLS.md 7.6）。 */\nint64_t extc_pool_rowColor(int64_t rid) {\n    int64_t zi;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return -1;\n    zi = extc_pools[rid].zone;\n    if (zi < 0 || zi > extc_zoneTop) return -1;\n    return extc_zones[zi].color;\n}\nint64_t extc_pool_birthColor(int64_t rid) {\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return -1;\n    return extc_pools[rid].color;\n}\nint64_t extc_pool_bytes(int64_t rid) {\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live) return 0;\n    return extc_pools[rid].bytes;\n}\nint64_t extc_pool_bytesLive(void) { return extc_poolBytesAll; }\n");
    bufPuts(out, "/* Grow or shrink one block, in place when the allocator can. `grow` uses this instead of\n * take + copy + give, and the reason is the peak: with a copy, the old and the new block\n * are both alive for the length of the copy, which measured 1.9x the live size (15,052 KB\n * for an 8 MB vector); growing in place stays near it. Bytes added at the end are zeroed,\n * so an element that was never written still reads as zero, as everywhere else. */\nvoid *extc_pool_resize(int64_t rid, void *p, int64_t bytes) {\n    ExtcBlock **link;\n    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live || !p) return NULL;\n    if (bytes <= 0) bytes = 1;\n    link = &extc_pools[rid].blocks;\n    while (*link) {\n        ExtcBlock *b = *link;\n        if ((void *)(b + 1) == p) {\n            int64_t old = b->size;\n            ExtcBlock *nb = (ExtcBlock *)realloc(b, sizeof(ExtcBlock) + (size_t)bytes);\n            if (!nb) { fprintf(stderr, \"trap: out of pool memory (this resize wanted %lld bytes)\\n\",\n                              (long long)bytes); extc_die(1); }\n            if (bytes > old) memset((char *)(nb + 1) + old, 0, (size_t)(bytes - old));\n            nb->size = bytes;\n            *link    = nb;\n            extc_pools[rid].bytes += bytes - old;\n            extc_poolBytesAll     += bytes - old;\n            return (void *)(nb + 1);\n        }\n        link = &b->next;\n    }\n    return NULL;\n}\n");
    /* `poolResizeRaw<T>(rid, s, n)`：与 `resize` 相同，只是**新长出来那一段不清零**。
     *
     * 什么时候能不清：那块内存**每一个槽都是先写后读**。容器的列/缓冲就是（`map` 的
     * `nodes`/`keys`/`vals`/`kids`、`vector`/`string` 的缓冲、`hashMap` 的
     * `keys`/`slot`/`bucketOfDense`）。清它是**纯多做**：写一遍马上被覆盖的字节，还顺手把
     * 「预留了但用不到」的页**提交掉**（RSS 的账）。
     * 反例必须继续走 `resize`：`hashMap` 的 `tag`（空桶就是 0）、`pool` 自己的 `ent`
     * （`pFree` 把 0 读作空闲）。
     * 实测（`bench/stl`，去掉这两处 memset）：map 时间 −3.7% / RSS −17.7%，string −6.0% /
     * −10.8%，vector −10.9%；容量有余量时最多 −40% / −46%。
     * 副作用面由 `tests/pool` 的毒化金丝雀钉住（`-DEXTC_POISON_RAW=1`）。 */
    bufPuts(out, "/* 与 `resize` 相同，只是新长出来那一段**不清零**（理由见 pools.c）。 */\n"
        "void *extc_pool_resize_raw(int64_t rid, void *p, int64_t bytes) {\n"
        "    ExtcBlock **link;\n"
        "    if (rid < 0 || rid >= extc_poolCap || !extc_pools[rid].live || !p) return NULL;\n"
        "    if (bytes <= 0) bytes = 1;\n"
        "    link = &extc_pools[rid].blocks;\n"
        "    while (*link) {\n"
        "        ExtcBlock *b = *link;\n"
        "        if ((void *)(b + 1) == p) {\n"
        "            int64_t old = b->size;\n"
        "            ExtcBlock *nb = (ExtcBlock *)realloc(b, sizeof(ExtcBlock) + (size_t)bytes);\n"
        "            if (!nb) { fprintf(stderr, \"trap: out of pool memory (this resize wanted %lld bytes)\\n\",\n"
        "                              (long long)bytes); extc_die(1); }\n"
        "#ifdef EXTC_POISON_RAW\n"
        "            if (bytes > old) memset((char *)(nb + 1) + old, 0xAA, (size_t)(bytes - old));\n"
        "#endif\n"
        "            nb->size = bytes;\n"
        "            *link    = nb;\n"
        "            extc_pools[rid].bytes += bytes - old;\n"
        "            extc_poolBytesAll     += bytes - old;\n"
        "            return (void *)(nb + 1);\n"
        "        }\n"
        "        link = &b->next;\n"
        "    }\n"
        "    return NULL;\n"
        "}\n");
}
